/**
 * @name Command Injection from CLI arguments
 * @description Detects command injection vulnerabilities where command line arguments are passed to subprocess calls.
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection-cli
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // sys.argv
    source = API::moduleImport("sys").getMember("argv").asSource()
    or
    // argparse.ArgumentParser().parse_args()
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("argparse").getMember("ArgumentParser").getReturn().getMember("parse_args").getACall() and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("subprocess").getMember(["call", "check_call", "run", "Popen"]).getACall() or
        call = API::moduleImport("os").getMember(["system", "popen"]).getACall()
      ) and
      (
        sink = call.getArg(0) or
        sink = call.getArgByName("args")
      )
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential command injection from $@.", source.getNode(), "CLI arguments"

/**
 * @name Marshal load source trace
 * @description Trace the file object passed to marshal.load
 * @kind path-problem
 * @problem.severity error
 * @id py/marshal-load-trace
 * @tags security
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module MarshalTraceConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Source is the return value of open()
    source = API::moduleImport("builtins").getMember("open").getACall()
    or
    source = API::moduleImport("io").getMember("open").getACall()
  }

  predicate isSink(DataFlow::Node sink) {
    sink = API::moduleImport("marshal").getMember("load").getACall().getArg(0)
  }
}

module MarshalTraceFlow = DataFlow::Global<MarshalTraceConfig>;
import MarshalTraceFlow::PathGraph

from MarshalTraceFlow::PathNode source, MarshalTraceFlow::PathNode sink
where MarshalTraceFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "marshal.load reads from this file opened at $@.", source.getNode(), "open()"
